(645746, 67552, 15919, '<td valign="top">You seem to have good sidelightning there.  About the image it self its hard to rate, the subject is fine but the background seems litle strange.</td>', 'You seem to have good sidelightning there.  About the image it self its hard to rate, the subject is fine but the background seems litle strange.', '2004-03-31 13:22:24.000000', NULL, 1),
(645750, 66652, 18676, '<td valign="top">Wow, this is very nice, maybe a ltitle too centered, but I love it.</td>', 'Wow, this is very nice, maybe a ltitle too centered, but I love it.', '2004-03-31 13:23:49.000000', NULL, 1),
(645753, 66938, 15919, '<td valign="top">Its great capture, your eyes are instantly fixed on the boy.  The angel is very good and also the lightning.  Maybe you should have give it a litle tighter croping from above.</td>', 'Its great capture, your eyes are instantly fixed on the boy.  The angel is very good and also the lightning.  Maybe you should have give it a litle tighter croping from above.', '2004-03-31 13:24:48.000000', NULL, 1),
