(645767, 66981, 18484, '<td valign="top">great use of colour</td>', 'great use of colour', '2004-03-31 13:30:28.000000', NULL, 1),
(645768, 67387, 11518, '<td valign="top">Beautiful picture, but I don''t see what''s out of place there...for this reason only I''m giving a 2, otherwise this is a 9 photo...</td>', 'Beautiful picture, but I don''t see what''s out of place there...for this reason only I''m giving a 2, otherwise this is a 9 photo...', '2004-03-31 13:30:50.000000', NULL, 1),
