INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(645783, 67455, 18484, '<td valign="top">great photojournalist perspective.</td>', 'great photojournalist perspective.', '2004-03-31 13:34:57.000000', NULL, 1),
(645785, 67046, 15129, '<td valign="top">IMHO, it would have worked better without so much gray and shadow--make the keys whiter to bring out contrast. Whiter keys would make the red one even more stunning. Good picture over all.</td>', 'IMHO, it would have worked better without so much gray and shadow--make the keys whiter to bring out contrast. Whiter keys would make the red one even more stunning. Good picture over all.', '2004-03-31 13:35:34.000000', NULL, 1),
(645786, 66975, 15919, '<td valign="top">Dont belive you baked them with the coins in them???  Technically well done and an original idea and setup.  The image though dont seem very eyecaching to me but I give you a credit for experimenting.</td>', 'Dont belive you baked them with the coins in them???  Technically well done and an original idea and setup.  The image though dont seem very eyecaching to me but I give you a credit for experimenting.', '2004-03-31 13:35:40.000000', NULL, 1),
