(645791, 67230, 18484, '<td valign="top">beautiful shot!</td>', 'beautiful shot!', '2004-03-31 13:37:59.000000', NULL, 1),
(645792, 67562, 18484, '<td valign="top">nice.</td>', 'nice.', '2004-03-31 13:38:25.000000', NULL, 1),
