(645799, 66640, 18191, '<td valign="top">Coo Coo Cachoo</td>', 'Coo Coo Cachoo', '2004-03-31 13:45:16.000000', NULL, 1),
(645803, 67450, 15129, '<td valign="top">Great idea, but over-exposed--especially the sky (also the modern buildings).</td>', 'Great idea, but over-exposed--especially the sky (also the modern buildings).', '2004-03-31 13:48:06.000000', NULL, 1),
(645805, 67351, 15129, '<td valign="top">Unfortunate that it''s out of focus and the lighting is too low, otherwise it would have been pretty cool.</td>', 'Unfortunate that it''s out of focus and the lighting is too low, otherwise it would have been pretty cool.', '2004-03-31 13:51:02.000000', NULL, 1),
(645806, 67293, 18191, '<td valign="top">Reflection on the 8 is way too harsh and distracting.</td>', 'Reflection on the 8 is way too harsh and distracting.', '2004-03-31 13:51:04.000000', NULL, 1),
(645809, 67381, 15129, '<td valign="top">Needs to be cropped quite a bit, I think. Also seems out of focus.</td>', 'Needs to be cropped quite a bit, I think. Also seems out of focus.', '2004-03-31 13:55:24.000000', NULL, 1),
