(646283, 67289, 16106, '<td valign="top">a two to one numerical advantage is not enough to isolate one color from the next for me, but what you did shoot is spot on! great lighting.</td>', 'a two to one numerical advantage is not enough to isolate one color from the next for me, but what you did shoot is spot on! great lighting.', '2004-03-31 18:24:28.000000', NULL, 1),
(646285, 67267, 18868, '<td valign="top">cool -- I was actually expecting to see lots of lame "game piece" ideas but yours actually delivers a clever conceptual pun, a soldier as a pawn.  The shot is a little flat and the DOF is sort of ''neither here nor there''.  It shows some blurring at the very front, but not enough to look intentional.</td>', 'cool -- I was actually expecting to see lots of lame "game piece" ideas but yours actually delivers a clever conceptual pun, a soldier as a pawn.  The shot is a little flat and the DOF is sort of ''neither here nor there''.  It shows some blurring at the very front, but not enough to look intentional.', '2004-03-31 18:25:22.000000', NULL, 1),
(646288, 67230, 6520, '<td valign="top">nice shot 8</td>', 'nice shot 8', '2004-03-31 18:26:53.000000', NULL, 1),
(646291, 67046, 16106, '<td valign="top">I have a keyboard like that. well framed . I think the light might be smoother as those shadows on the numerical keys are distracting.</td>', 'I have a keyboard like that. well framed . I think the light might be smoother as those shadows on the numerical keys are distracting.', '2004-03-31 18:27:49.000000', NULL, 1),
