(646483, 67118, 16093, '<td valign="top">Stunning. Beautiful. Breath taking. Mystical, magical, enchanting. Awesome.</td>', 'Stunning. Beautiful. Breath taking. Mystical, magical, enchanting. Awesome.', '2004-03-31 20:22:56.000000', NULL, 1),
(646489, 67519, 15207, '<td valign="top">Extremely disturbing, esp. with the lid on it, but an effective and provocative image for this challenge. I''m giving this a 9 because it is also an extremely sharp and well-composed image. For some reason quite a few entries int his challenge weren''t even in focus. This is very sharp and crisp. Very cute bunny rabits by the way!</td>', 'Extremely disturbing, esp. with the lid on it, but an effective and provocative image for this challenge. I''m giving this a 9 because it is also an extremely sharp and well-composed image. For some reason quite a few entries int his challenge weren''t even in focus. This is very sharp and crisp. Very cute bunny rabits by the way!', '2004-03-31 20:27:46.000000', NULL, 1),
(646491, 67479, 15207, '<td valign="top">My favorite. I hope you win!</td>', 'My favorite. I hope you win!', '2004-03-31 20:27:59.000000', NULL, 1),
