(646574, 66533, 19309, '<td valign="top">Being a fan of B&amp;W photography, this is a very wonderful image.  It has an "old" feeling to it; kinda makes you think of a pair of dusty shoes and an old wedding veil that were kept up in the attic for many years (years of heritage flowing through them).</td>', 'Being a fan of B&W photography, this is a very wonderful image.  It has an "old" feeling to it; kinda makes you think of a pair of dusty shoes and an old wedding veil that were kept up in the attic for many years (years of heritage flowing through them).', '2004-03-31 21:15:39.000000', NULL, 1),
(646576, 67359, 17802, '<td valign="top">There is a laundry detergent call "HAS"?</td>', 'There is a laundry detergent call "HAS"?', '2004-03-31 21:16:25.000000', NULL, 1),
(646577, 67012, 18868, '<td valign="top">Another shooter had exactly the same idea -- yours is significantly better technically.</td>', 'Another shooter had exactly the same idea -- yours is significantly better technically.', '2004-03-31 21:17:26.000000', NULL, 1),
(646579, 67450, 19309, '<td valign="top">Beautiful image.  The color is great; the effects are great...everything!</td>', 'Beautiful image.  The color is great; the effects are great...everything!', '2004-03-31 21:17:43.000000', NULL, 1),
(646580, 67315, 16479, '<td valign="top">lol....nice shot but a bit dark....</td>', 'lol....nice shot but a bit dark....', '2004-03-31 21:18:03.000000', NULL, 1),
