INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(646595, 67524, 8522, '<td valign="top">Nice idea, shame it''s overexposed. I wish it was a more imaginative composition... next time try placing your point of focus on one of the intersections of thirds.</td>', 'Nice idea, shame it''s overexposed. I wish it was a more imaginative composition... next time try placing your point of focus on one of the intersections of thirds.', '2004-03-31 21:27:17.000000', NULL, 1),
(646596, 67562, 8522, '<td valign="top">Interesting shot... focus seems to be slightly off though.</td>', 'Interesting shot... focus seems to be slightly off though.', '2004-03-31 21:29:42.000000', NULL, 1),
(646598, 67084, 18833, '<td valign="top">I really like the idea of this photo, but the neat freak in me wishes the cans were all the same size.</td>', 'I really like the idea of this photo, but the neat freak in me wishes the cans were all the same size.', '2004-03-31 21:30:48.000000', NULL, 1),
