(646876, 67492, 3306, '<td valign="top">I think your fly is down. Very unusual picture but I have to appreciate your unique sense of humor.</td>', 'I think your fly is down. Very unusual picture but I have to appreciate your unique sense of humor.', '2004-04-01 00:00:27.000000', NULL, 1),
(646878, 67158, 9747, '<td valign="top">Not sure how this relates to the theme. Is the guy a wrestler who is out of the ring? Looks like a picture of a scene on TV? Overall image is too blurry and the colors are blotched.</td>', 'Not sure how this relates to the theme. Is the guy a wrestler who is out of the ring? Looks like a picture of a scene on TV? Overall image is too blurry and the colors are blotched.', '2004-04-01 00:01:12.000000', NULL, 1),
