(654659, 67238, 19342, '<td valign="top">I really like this one.  I like the lighting showing the translucency of the real eggs.  Plus, I love Cadbury creme eggs.</td>', 'I really like this one.  I like the lighting showing the translucency of the real eggs.  Plus, I love Cadbury creme eggs.', '2004-04-05 17:39:57.000000', NULL, 1),
(654660, 67362, 13136, '<td valign="top">Too overexposed. I can only guess that the lake is frozen?</td>', 'Too overexposed. I can only guess that the lake is frozen?', '2004-04-05 17:40:59.000000', NULL, 1),
