(654665, 66769, 13136, '<td valign="top">Very cool concept. Too bad you can''t get rid of the haze created by the water. Well executed.</td>', 'Very cool concept. Too bad you can''t get rid of the haze created by the water. Well executed.', '2004-04-05 17:43:04.000000', NULL, 1),
(654669, 67387, 13136, '<td valign="top">Very nice picture. Out of Place? I''m sorry, but I don''t see it.</td>', 'Very nice picture. Out of Place? I''m sorry, but I don''t see it.', '2004-04-05 17:51:09.000000', NULL, 1),
(654708, 66891, 16982, '<td valign="top">The composition is great but the light is a bit depressing.</td>', 'The composition is great but the light is a bit depressing.', '2004-04-05 18:36:49.000000', NULL, 1),
(654730, 67347, 16965, '<td valign="top">interesting DOF on this image. We have bright images in the foreground and dark images in the background.   My eye is drawn to the bright yellow and orange in the foreground, but it isn''t in focus, so I keep bouncing around the image.  perhaps the image would have been more apealing if it weren''t so confusing!</td>', 'interesting DOF on this image. We have bright images in the foreground and dark images in the background.   My eye is drawn to the bright yellow and orange in the foreground, but it isn''t in focus, so I keep bouncing around the image.  perhaps the image would have been more apealing if it weren''t so confusing!', '2004-04-05 18:56:24.000000', NULL, 1),
(654731, 67553, 16982, '<td valign="top">I like this one.  My main complaint is that there is very little at the focal point of the picture, and quite a lot of water...but I suppose that was the point.  Very good feeling of movement from the water drops.</td>', 'I like this one.  My main complaint is that there is very little at the focal point of the picture, and quite a lot of water...but I suppose that was the point.  Very good feeling of movement from the water drops.', '2004-04-05 18:57:00.000000', NULL, 1),
(654744, 67502, 16965, '<td valign="top">the over - exposure is a bit taxing to the eyes.</td>', 'the over - exposure is a bit taxing to the eyes.', '2004-04-05 19:05:18.000000', NULL, 1),
(654775, 67552, 16126, '<td valign="top">Nice composition, lighting maybe a bit harsh, seems a tiny bit unsharp</td>', 'Nice composition, lighting maybe a bit harsh, seems a tiny bit unsharp', '2004-04-05 19:46:53.000000', NULL, 1),
(654782, 66894, 5391, '<td valign="top">Interesting lighting effects.  I wish the bright highlight were on the "out of place" coin, to draw attention to it.  Better focus would also help.</td>', 'Interesting lighting effects.  I wish the bright highlight were on the "out of place" coin, to draw attention to it.  Better focus would also help.', '2004-04-05 19:53:13.000000', NULL, 1),
(654787, 67520, 5391, '<td valign="top">This is a lovely shot, but I''m distracted by what seems to be horizon tilt - may or may not be, due to your relation to the dock, but it pulls my attention away from the beached boat.</td>', 'This is a lovely shot, but I''m distracted by what seems to be horizon tilt - may or may not be, due to your relation to the dock, but it pulls my attention away from the beached boat.', '2004-04-05 19:55:14.000000', NULL, 1),
(654789, 67453, 5391, '<td valign="top">Excellent shot for this challenge!  Compostion is also very good.  Nice work.</td>', 'Excellent shot for this challenge!  Compostion is also very good.  Nice work.', '2004-04-05 19:57:20.000000', NULL, 1),
(654816, 67526, 2158, '<td valign="top">This is really funny.  I like it a lot.</td>', 'This is really funny.  I like it a lot.', '2004-04-05 20:31:53.000000', NULL, 1),
(654822, 67293, 15982, '<td valign="top">Nice composition! I would like to know how many eggs you used! Hopefully you boiled them because that would have been quite a mess!!!! The lighting and color look strong as well. One of my favorites. 10</td>', 'Nice composition! I would like to know how many eggs you used! Hopefully you boiled them because that would have been quite a mess!!!! The lighting and color look strong as well. One of my favorites. 10', '2004-04-05 20:39:34.000000', NULL, 1),
(654823, 67381, 15982, '<td valign="top">a tighter crop off the bottom, the absence of the little white car and a wider aperture/ faster shutter speed would have made this picture so much better. your subject is really awesome though and the overall composition is powerful. just typical dpc nit-picking. i would like to play around with this picture in PS to subtract the car, crop tighter at the bottom and adjust levels and shadow/highlights to give it more pizzaz. only by your permission though. good luck!!! 6</td>', 'a tighter crop off the bottom, the absence of the little white car and a wider aperture/ faster shutter speed would have made this picture so much better. your subject is really awesome though and the overall composition is powerful. just typical dpc nit-picking. i would like to play around with this picture in PS to subtract the car, crop tighter at the bottom and adjust levels and shadow/highlights to give it more pizzaz. only by your permission though. good luck!!! 6', '2004-04-05 20:47:25.000000', NULL, 1),
(654824, 67524, 15982, '<td valign="top">WAY too much flash!!!! i would like to suggest a tripod, a lower aperture (f/stop) value, maybe faster shutter speed, and light source or two. if you cannot set the aperture value or shutter speed then i would suggest a bright light source and plenty of daylight. flashes tend to produce a very harsh light - and yours has burned several spots fairly badly with blown out white. i hope this provides some useful help. not a bad idea though. good luck!</td>', 'WAY too much flash!!!! i would like to suggest a tripod, a lower aperture (f/stop) value, maybe faster shutter speed, and light source or two. if you cannot set the aperture value or shutter speed then i would suggest a bright light source and plenty of daylight. flashes tend to produce a very harsh light - and yours has burned several spots fairly badly with blown out white. i hope this provides some useful help. not a bad idea though. good luck!', '2004-04-05 20:52:19.000000', NULL, 1),
(654830, 67267, 15982, '<td valign="top">i think this is quite funny! i would recommend a shallow depth of field on the soldier to make him stand out more though. good choice (imo) with b&amp;w tones though. i think a little different vantage point would have made the comp more interesting too. good luck!</td>', 'i think this is quite funny! i would recommend a shallow depth of field on the soldier to make him stand out more though. good choice (imo) with b&w tones though. i think a little different vantage point would have made the comp more interesting too. good luck!', '2004-04-05 20:58:18.000000', NULL, 1),
(654832, 67535, 15982, '<td valign="top">i feel that a stronger comp would have this an amazing picture. i love the subject and the use of background and fill in the picture.  maybe even a little tighter crop/ closer zoom on the subject to make it stand out more too. great idea though - you have my bias because i love MC Escher, one of my favorite artists!!</td>', 'i feel that a stronger comp would have this an amazing picture. i love the subject and the use of background and fill in the picture.  maybe even a little tighter crop/ closer zoom on the subject to make it stand out more too. great idea though - you have my bias because i love MC Escher, one of my favorite artists!!', '2004-04-05 21:02:19.000000', NULL, 1),
(654835, 67492, 15982, '<td valign="top">...minus the bugs, not a bad idea. strange, but creative.</td>', '...minus the bugs, not a bad idea. strange, but creative.', '2004-04-05 21:03:43.000000', NULL, 1),
(654872, 66521, 15407, '<td valign="top">You''ve created quite an intriguing photo... Out of place...naw...  I''m the one outta place.... wish I''d have been there!</td>', 'You''ve created quite an intriguing photo... Out of place...naw...  I''m the one outta place.... wish I''d have been there!', '2004-04-05 21:29:39.000000', NULL, 1),
(654883, 67230, 17203, '<td valign="top">Very good shot of the duck, but not enough context to show why it''s out of place. If it weren''t for the title, I wouldn''t know. Also, you need to rotate the shot to get the wall straight.</td>', 'Very good shot of the duck, but not enough context to show why it''s out of place. If it weren''t for the title, I wouldn''t know. Also, you need to rotate the shot to get the wall straight.', '2004-04-05 21:43:22.000000', NULL, 1),
(654905, 66998, 2158, '<td valign="top">Good idea, but I''d have removed the other stuff from the table.  It''s just too distracting.</td>', 'Good idea, but I''d have removed the other stuff from the table.  It''s just too distracting.', '2004-04-05 22:02:44.000000', NULL, 1),
(654918, 67490, 19022, '<td valign="top">Great Idea!!  Great Lighting!</td>', 'Great Idea!!  Great Lighting!', '2004-04-05 22:28:04.000000', NULL, 1),
(654923, 67448, 2158, '<td valign="top">A bit of the effect is lost because of the dark sleeve behind the ''coffee''.  On a more technical note, you have lost some detail by over-compressing the file.  Otherwise, well done.</td>', 'A bit of the effect is lost because of the dark sleeve behind the ''coffee''.  On a more technical note, you have lost some detail by over-compressing the file.  Otherwise, well done.', '2004-04-05 22:35:16.000000', NULL, 1),
(654926, 67479, 17203, '<td valign="top">Ribbon, Blue.<br/>0010</td>', 'Ribbon, Blue.0010', '2004-04-05 22:37:35.000000', NULL, 1),
(654941, 67056, 2158, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2004-04-05 22:59:40.000000', NULL, 1),
(654942, 66521, 19174, '<td valign="top">What''s so out of place about this?</td>', 'What''s so out of place about this?', '2004-04-05 23:00:36.000000', NULL, 1),
(654957, 66938, 9747, '<td valign="top">Not sure if this fits the theme perfectly as there are a couple other kids (besides the boy in the center) who are also not blurred. But at the same time, I can see how it fits into the theme. ;-) This is a great portrait shot of the boy - if you plan to print this, I''d suggest cropping or cloning out the distracting microphone stand. I like the blur effect made by other kids. Cute kids, lovely shot!</td>', 'Not sure if this fits the theme perfectly as there are a couple other kids (besides the boy in the center) who are also not blurred. But at the same time, I can see how it fits into the theme. ;-) This is a great portrait shot of the boy - if you plan to print this, I''d suggest cropping or cloning out the distracting microphone stand. I like the blur effect made by other kids. Cute kids, lovely shot!', '2004-04-05 23:18:54.000000', NULL, 1),
(654964, 67479, 9747, '<td valign="top">This got a big chuckle out of me! I think it''d be hilarious if you showed Santa''s face. Then again, without seeing Santa''s face, this prompts the viewer to conjure up various stories and imaginations. Just the idea of Santa Claus being booked is too funny. Great composition/color, good pose, looks realistic, and fits the theme perfectly. Bravo!</td>', 'This got a big chuckle out of me! I think it''d be hilarious if you showed Santa''s face. Then again, without seeing Santa''s face, this prompts the viewer to conjure up various stories and imaginations. Just the idea of Santa Claus being booked is too funny. Great composition/color, good pose, looks realistic, and fits the theme perfectly. Bravo!', '2004-04-05 23:25:36.000000', NULL, 1),
(654968, 67381, 10818, '<td valign="top">Thats a great entry...I would have maybe chopped off some of the green grass in the front, it really does not add anything....but a perfect submission to the contest..nice job.</td>', 'Thats a great entry...I would have maybe chopped off some of the green grass in the front, it really does not add anything....but a perfect submission to the contest..nice job.', '2004-04-05 23:29:16.000000', NULL, 1),
(654972, 67428, 9747, '<td valign="top">Wow, very cool! I figure the subject is lying on a glass panel (the vertical post thingy must be the framing?). In any case, it''s an eye-catching image and does give one an impression of a floating/flying lady. Too bad the jacket is there, otherwise the visual impact would''ve been greater. Overall a wonderful photo, just needs a bit more contrast, I think.</td>', 'Wow, very cool! I figure the subject is lying on a glass panel (the vertical post thingy must be the framing?). In any case, it''s an eye-catching image and does give one an impression of a floating/flying lady. Too bad the jacket is there, otherwise the visual impact would''ve been greater. Overall a wonderful photo, just needs a bit more contrast, I think.', '2004-04-05 23:35:36.000000', NULL, 1),
(654973, 66633, 14805, '<td valign="top">I like your idea.  you should try incrasing the contrast in photoshop to make the image stick out a little more. but good pic.</td>', 'I like your idea.  you should try incrasing the contrast in photoshop to make the image stick out a little more. but good pic.', '2004-04-05 23:35:47.000000', NULL, 1),
(654979, 67417, 9747, '<td valign="top">A bit dull, dark, and blurry. The lines of light (cars'' headllights) are too far apart from each other, causing too loose a composition for this image. You''ve got a good concept though, and you captured the cars'' headlights very nicely.</td>', 'A bit dull, dark, and blurry. The lines of light (cars'' headllights) are too far apart from each other, causing too loose a composition for this image. You''ve got a good concept though, and you captured the cars'' headlights very nicely.', '2004-04-05 23:40:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(654983, 66533, 12268, '<td valign="top">i would have scored this a 10 if it were not so small. 7</td>', 'i would have scored this a 10 if it were not so small. 7', '2004-04-05 23:44:41.000000', NULL, 1),
(654994, 66968, 9747, '<td valign="top">I see the double exposure, but overall, the picture is too cluttered and confusing. The title gave me a hint on what''s happening, but without it, I don''t understand what''s going on here. It''s understandable if you were short on time and/or in a wrong place, but next time try to plan ahead. Nice attempt.</td>', 'I see the double exposure, but overall, the picture is too cluttered and confusing. The title gave me a hint on what''s happening, but without it, I don''t understand what''s going on here. It''s understandable if you were short on time and/or in a wrong place, but next time try to plan ahead. Nice attempt.', '2004-04-06 00:02:34.000000', NULL, 1),
(654996, 67382, 17551, '<td valign="top">I like the lighting and soft focus.. I assume what your trying to capture is someone feeling out of place. Good fresh originality. I do think the border is a bit large though... 7</td>', 'I like the lighting and soft focus.. I assume what your trying to capture is someone feeling out of place. Good fresh originality. I do think the border is a bit large though... 7', '2004-04-06 00:06:46.000000', NULL, 1),
