(655001, 66916, 17551, '<td valign="top">background sheet needs to absolutely spotless.. lighting is a bit too harsh.</td>', 'background sheet needs to absolutely spotless.. lighting is a bit too harsh.', '2004-04-06 00:08:57.000000', NULL, 1),
(655002, 66894, 17551, '<td valign="top">ouch.. looking to focus on something but cant.. my eyes!</td>', 'ouch.. looking to focus on something but cant.. my eyes!', '2004-04-06 00:09:25.000000', NULL, 1),
(655004, 67490, 17551, '<td valign="top">hey.. the colouring and silhouetting/lighting is fantastic.. just not that interesting of a composition :-( sorry.. 5</td>', 'hey.. the colouring and silhouetting/lighting is fantastic.. just not that interesting of a composition :-( sorry.. 5', '2004-04-06 00:10:34.000000', NULL, 1),
(655005, 67019, 17551, '<td valign="top">great clothes for the boy.. and the wall even has character.. not really sure why he is out of place though.. 6</td>', 'great clothes for the boy.. and the wall even has character.. not really sure why he is out of place though.. 6', '2004-04-06 00:11:31.000000', NULL, 1),
(655006, 67500, 17551, '<td valign="top">strange, certainly the flowers seem out of place, but I was hoping the title would give more clues as to why</td>', 'strange, certainly the flowers seem out of place, but I was hoping the title would give more clues as to why', '2004-04-06 00:13:24.000000', NULL, 1),
(655009, 67507, 17551, '<td valign="top">cute kid</td>', 'cute kid', '2004-04-06 00:20:47.000000', NULL, 1),
