(655513, 67230, 13897, '<td valign="top">This is my favorite shot this challenge. Great freeze on the duck. I have them in my lake where I live and know how hard this shot is to get. Good luck.</td>', 'This is my favorite shot this challenge. Great freeze on the duck. I have them in my lake where I live and know how hard this shot is to get. Good luck.', '2004-04-06 12:58:21.000000', NULL, 1),
(655517, 67553, 18897, '<td valign="top">Very amusing shot and a good interpretation of the topic. Colors and focus aren''t the best, but I''ll mark it up for originality anyway.</td>', 'Very amusing shot and a good interpretation of the topic. Colors and focus aren''t the best, but I''ll mark it up for originality anyway.', '2004-04-06 13:03:24.000000', NULL, 1),
(655521, 67293, 18897, '<td valign="top">Not sure if it''s subconscious, but I feel an urge to give this one an 8.. Must resist.. Can''t..</td>', 'Not sure if it''s subconscious, but I feel an urge to give this one an 8.. Must resist.. Can''t..', '2004-04-06 13:06:02.000000', NULL, 1),
